from collections import deque
R,C=5,12
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==0 and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); comp=[]
   for x,y in q:
    comp.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<R and 0<=b<C and grid[a][b]==0 and (a,b) not in seen:
      seen.add((a,b)); q.append((a,b))
   comps.append(comp)
[(len(x), min(x),any(r in (0,R-1) or c in (0,C-1) for r,c in x), sorted(x)) for x in comps]
